use bulletproofs::{BulletproofGens, PedersenGens, RangeProof};
use curve25519_dalek::scalar::Scalar;
use merlin::Transcript;
use rand::{rngs::StdRng, SeedableRng, TryRng, TryCryptoRng};
use std::convert::Infallible;
// Test-only chosen entropy output; this is deliberately not a secure generator.
struct Factor(u8);
impl TryRng for Factor {
    type Error = Infallible;
    fn try_next_u32(&mut self) -> Result<u32, Infallible> { Ok(self.0 as u32) }
    fn try_next_u64(&mut self) -> Result<u64, Infallible> { Ok(self.0 as u64) }
    fn try_fill_bytes(&mut self, dst: &mut [u8]) -> Result<(), Infallible> {
        dst.fill(0); if !dst.is_empty() { dst[0] = self.0; } Ok(())
    }
}
impl TryCryptoRng for Factor {}
fn main() {
    let bp=BulletproofGens::new(8,1);
    let pc=PedersenGens::default();
    let mut rng=StdRng::seed_from_u64(20260909);
    let (proof, values)=RangeProof::prove_multiple_with_rng(&bp,&pc,&mut Transcript::new(b"factor-probe"),&[42],&[Scalar::from(17u64)],8,&mut rng).expect("prove");
    let mut bytes=proof.to_bytes();
    let tx=Option::<Scalar>::from(Scalar::from_canonical_bytes(bytes[128..160].try_into().expect("scalar bytes"))).expect("canonical response");
    bytes[128..160].copy_from_slice(&(tx+Scalar::ONE).to_bytes());
    let invalid=RangeProof::from_bytes(&bytes).expect("decodable altered response");
    let zero=invalid.verify_multiple_with_rng(&bp,&pc,&mut Transcript::new(b"factor-probe"),&values,8,&mut Factor(0)).is_ok();
    let one=invalid.verify_multiple_with_rng(&bp,&pc,&mut Transcript::new(b"factor-probe"),&values,8,&mut Factor(1)).is_ok();
    println!("{{\"zero_factor_accepts\":{zero},\"one_factor_accepts\":{one}}}");
    assert!(zero && !one);
}
